from dataclasses import dataclass
import math
from numbers import Real


@dataclass(frozen=True)
class Track:
    track_id: str
    width: float
    start: tuple
    end: tuple


@dataclass(frozen=True)
class Segment:
    segment_id: str
    start: tuple
    end: tuple
    tracks: tuple


@dataclass(frozen=True)
class RailPlan:
    plan_id: str
    name: str
    segments: tuple


def _number(value, *, positive=False, nonnegative=False):
    if isinstance(value, bool) or not isinstance(value, Real):
        raise ValueError("expected a real number")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError("numbers must be finite")
    if positive and result <= 0:
        raise ValueError("number must be positive")
    if nonnegative and result < 0:
        raise ValueError("number must be nonnegative")
    return result


def build_rail_plan(data):
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")
    if set(data) != {"plan_id", "name", "segments"}:
        raise ValueError("invalid plan fields")
    plan_id = data["plan_id"]
    name = data["name"]
    raw_segments = data["segments"]
    if not isinstance(plan_id, str) or not plan_id:
        raise ValueError("invalid plan_id")
    if not isinstance(name, str) or not name:
        raise ValueError("invalid name")
    if not isinstance(raw_segments, list):
        raise ValueError("segments must be a list")

    segments = []
    segment_ids = set()
    for raw in raw_segments:
        if not isinstance(raw, dict) or set(raw) != {"id", "start", "length", "heading", "tracks"}:
            raise ValueError("invalid segment")
        segment_id = raw["id"]
        if not isinstance(segment_id, str) or not segment_id or segment_id in segment_ids:
            raise ValueError("invalid or duplicate segment id")
        segment_ids.add(segment_id)
        point = raw["start"]
        if not isinstance(point, (list, tuple)) or len(point) != 2:
            raise ValueError("start must contain two coordinates")
        start = (_number(point[0]), _number(point[1]))
        length = _number(raw["length"], nonnegative=True)
        heading = math.radians(_number(raw["heading"]))
        direction = (math.cos(heading), math.sin(heading))
        perpendicular = (direction[1], -direction[0])
        end = (start[0] + length * direction[0], start[1] + length * direction[1])

        raw_tracks = raw["tracks"]
        if not isinstance(raw_tracks, list) or not raw_tracks:
            raise ValueError("tracks must be a non-empty list")
        parsed = []
        track_ids = set()
        for raw_track in raw_tracks:
            if not isinstance(raw_track, dict) or set(raw_track) != {"id", "width"}:
                raise ValueError("invalid track")
            track_id = raw_track["id"]
            if not isinstance(track_id, str) or not track_id or track_id in track_ids:
                raise ValueError("invalid or duplicate track id")
            track_ids.add(track_id)
            parsed.append((track_id, _number(raw_track["width"], positive=True)))

        total_width = sum(width for _, width in parsed)
        consumed = 0.0
        tracks = []
        for track_id, width in parsed:
            offset = -total_width / 2.0 + consumed + width / 2.0
            track_start = (start[0] + offset * perpendicular[0], start[1] + offset * perpendicular[1])
            track_end = (end[0] + offset * perpendicular[0], end[1] + offset * perpendicular[1])
            tracks.append(Track(track_id, width, track_start, track_end))
            consumed += width
        segments.append(Segment(segment_id, start, end, tuple(tracks)))

    return RailPlan(plan_id, name, tuple(segments))

